const cntL=(r,f)=>{const m={};r.forEach(x=>(f(x)||[]).forEach(v=>m[v]=(m[v]||0)+1));return m};
const tp=m=>Object.entries(m).sort((a,b)=>b[1]-a[1])[0]||['—',0];
const keys=(m,o)=>o?o.filter(x=>m[x]):Object.keys(m).sort((a,b)=>m[b]-m[a]);
