function filterLabel(field,value){return field=='r'?RL[value]||value:String(value)}
function activateChartFilter(id,index,datasetIndex){
 const meta=CHMETA[id];if(!meta)return;
 let filters,label;
 if(meta.custom){
  const choice=meta.custom[index];if(!choice)return;
  filters=[{key:choice.key,test:choice.test}];label=choice.label;
 }else{
  if(meta.values[index]==null)return;
  const value=meta.values[index];filters=[{field:meta.field,value,multiple:meta.multiple}];
  label=filterLabel(meta.field,value);
 }
 if(meta.stacked){
  const status=RK[datasetIndex];if(!status)return;
  filters.push({field:'r',value:status});
  label=meta.categoryLabel+': '+filterLabel(meta.field,meta.values[index])+' · '+RL[status];
 }
 const key=filters.map(f=>(f.key||f.field)+':'+String(f.value)).join('|');
 if(quickFilters[id]&&quickFilters[id].key==key)delete quickFilters[id];
 else quickFilters[id]={key,label,filters};
 apply();
}
function mk(id,type,labels,sets,o={}){if(CH[id])CH[id].destroy();
 const tx=getComputedStyle(document.body).color,gr=getComputedStyle(document.body).getPropertyValue('--bd');
 if(type=='bar'&&o.h)$(id).parentElement.style.height=Math.max(300,labels.length*38+60)+'px';
 const axis={stacked:o.st,grid:{color:gr},ticks:{color:tx,autoSkip:false,font:{size:11}},max:o.max};
 const sc=type=='bar'?{x:{...axis,title:{display:true,text:o.h?(o.valueAxis||'Personas'):'Grupos',color:tx}},y:{...axis,title:{display:true,text:o.h?'Grupos':(o.valueAxis||'Personas'),color:tx}}}:type=='radar'?{r:{beginAtZero:true,max:100,ticks:{color:tx,backdropColor:'transparent',stepSize:20},grid:{color:gr},angleLines:{color:gr},pointLabels:{color:tx,font:{size:10}}}}:{};
 if(type=='bar'&&o.h){sc.x.max=o.max;sc.y.max=undefined}else if(type=='bar'){sc.y.max=o.max;sc.x.max=undefined}
 CH[id]=new Chart($(id),{type,data:{labels,datasets:sets},plugins:[ChartDataLabels],options:{indexAxis:o.h?'y':'x',responsive:true,maintainAspectRatio:false,layout:{padding:{right:o.h?44:8,top:8}},scales:sc,
 plugins:{legend:{display:o.leg!==false,position:'bottom',labels:{color:tx,boxWidth:12,padding:14}},datalabels:{color:c=>o.st||type=='pie'||type=='doughnut'||type=='polarArea'?'#fff':tx,font:{weight:'bold',size:10},textStrokeColor:'#101820',textStrokeWidth:2,anchor:c=>o.st?'center':'end',align:c=>o.st?'center':'end',clamp:true,clip:false,formatter:o.fm||(v=>v||''),display:c=>{const v=c.dataset.data[c.dataIndex];return !!v&&(!o.st||v>=(pct?8:2))}},
 tooltip:{callbacks:o.tt||{}}},onClick:(event,elements)=>{if(elements.length)activateChartFilter(id,elements[0].index,elements[0].datasetIndex)}}})}
function single(id,type,m,base,order,o={}){const k=keys(m,order),v=k.map(x=>m[x]);
 CHMETA[id]={field:SINGLE_FIELDS[id],values:k,multiple:['c7','c9','c12','c14'].includes(id)};
 const col=o.col||k.map((x,i)=>PAL[i%PAL.length]);const bar=type=='bar';
 mk(id,type,k,[{data:v,backgroundColor:col,borderColor:'#151f2b',borderWidth:2}],{leg:!bar&&type!='radar',h:o.h,valueAxis:'Personas',dl:'#fff',fm:x=>x+' · '+P(x,base)+'%',
 tt:{label:c=>c.label+': '+c.raw+' respuestas ('+P(c.raw,base)+'% de la base)'}})}
function stack(id,ks,fn,h){const tot=ks.map(k=>F.filter(r=>fn(r)==k).length);
 CHMETA[id]={field:STACK_FIELDS[id],values:ks,stacked:true,categoryLabel:STACK_FIELDS[id]=='a'?'Edad':STACK_FIELDS[id]=='c'?'Carrera':STACK_FIELDS[id]=='g'?'Género':'Educación financiera'};
 const ds=RK.map(q=>({label:RL[q],backgroundColor:RC[q],borderColor:'#151f2b',borderWidth:1,data:ks.map((k,i)=>{const n=F.filter(r=>fn(r)==k&&r.r==q).length;return pct?P(n,tot[i]):n})}));
 mk(id,'bar',ks.map((k,i)=>k+' (n='+tot[i]+')'),ds,{st:true,h,max:pct?100:undefined,valueAxis:pct?'% del grupo':'Personas',fm:v=>v?v+(pct?'%':''):'',tt:{label:c=>{const count=pct?Math.round(c.raw*tot[c.dataIndex]/100):c.raw;return c.dataset.label+': '+count+' personas ('+P(count,tot[c.dataIndex])+'% del grupo)'}}})}
const N=(id,h)=>{$('n'+id).innerHTML=h};
function renderQuickFilters(){
 const container=$('activeFilters');container.innerHTML='';
 const entries=Object.entries(quickFilters);
 if(entries.length){
  const label=document.createElement('span');label.className='active-filters-label';label.textContent='Explorando:';container.append(label);
 }
 entries.forEach(([id,selection])=>{
  const chip=document.createElement('button');chip.type='button';chip.className='filter-chip';
  chip.textContent=selection.label+' ×';chip.title='Quitar filtro: '+selection.label;
  chip.onclick=()=>{delete quickFilters[id];apply()};
  container.append(chip);
 });
 Object.keys(CHMETA).forEach(id=>{
  const selected=!!quickFilters[id],card=$('clear-'+id).closest('.c');
  $('clear-'+id).hidden=!selected;card.classList.toggle('chart-selected',selected);
 });
}
