 const mx=sg.slice().sort((x,y)=>y[1]-x[1])[0];N('c13',`La señal más extendida es <b>${mx[0]}</b> (${mx[1]}%). Además, ${P(B.filter(r=>r.ia=='Sí').length,be)}% de quienes respondieron a esa pregunta intentó reducir.`);
 const pu=cnt(F,r=>r.pu);single('c15','bar',pu,n,ORD.pu,{col:['#4d908e']});const fp=P((pu['Frecuentemente']||0)+(pu['Muy frecuentemente']||0),n);
