 const eo=cntL(F.filter(r=>r.ef=='Sí'),r=>r.eo),be2=F.filter(r=>r.ef=='Sí').length;single('c9','bar',eo,be2,null,{h:true,col:['#2a6f97']});const t9=tp(eo);
